--
-- Table structure for table `ventes_annuler`
--

CREATE TABLE `ventes_annuler` (
  `id` int NOT NULL DEFAULT '0',
  `type_vente` enum('livrer','usine') CHARACTER SET utf8mb3 NOT NULL,
  `quantite` int NOT NULL,
  `observation` varchar(255) CHARACTER SET utf8mb3 DEFAULT NULL,
  `type_paiement` enum('total','echellonner') CHARACTER SET utf8mb3 NOT NULL,
  `montant` float NOT NULL,
  `prix_unitaire` float NOT NULL,
  `date_vente` date NOT NULL,
  `id_client` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `user` int NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

