--
-- Structure for view `paiement_retard`
--
DROP TABLE IF EXISTS `paiement_retard`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `paiement_retard`  AS SELECT `r1`.`id` AS `id`, `r1`.`montant_vente` AS `montant_vente`, `r2`.`id_vente` AS `id_vente`, `r2`.`montant_paye` AS `montant_paye` FROM ((select `ventes`.`id` AS `id`,`ventes`.`montant` AS `montant_vente` from `ventes`) `r1` left join (select `paiements`.`id_vente` AS `id_vente`,sum(`paiements`.`montant`) AS `montant_paye` from `paiements` group by `paiements`.`id_vente`) `r2` on((`r1`.`id` = `r2`.`id_vente`))) WHERE (`r1`.`montant_vente` > `r2`.`montant_paye`) ;

