--
-- Structure for view `situation_depense_vente_30`
--
DROP TABLE IF EXISTS `situation_depense_vente_30`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `situation_depense_vente_30`  AS WITH recursive   `dates_table` as (select curdate() AS `date_jour` union all select (`dates_table`.`date_jour` - interval 1 day) AS `DATE_SUB(date_jour, INTERVAL 1 DAY)` from `dates_table` where (`dates_table`.`date_jour` > (curdate() - interval 29 day))) select `d`.`date_jour` AS `date_jour`,dayofmonth(`d`.`date_jour`) AS `jour`,coalesce(`v`.`total_ventes`,0) AS `total_ventes`,coalesce(`dep`.`total_depenses`,0) AS `total_depenses` from ((`dates_table` `d` left join (select cast(`situation_detail_vente`.`jour` as date) AS `date_vente`,sum(`situation_detail_vente`.`total_ventes`) AS `total_ventes` from `situation_detail_vente` where ((`situation_detail_vente`.`jour` >= (curdate() - interval 30 day)) and (`situation_detail_vente`.`jour` <= curdate())) group by cast(`situation_detail_vente`.`jour` as date)) `v` on((`d`.`date_jour` = `v`.`date_vente`))) left join (select cast(`situation_detail_depense`.`jour` as date) AS `date_depense`,sum(`situation_detail_depense`.`total_depenses`) AS `total_depenses` from `situation_detail_depense` where ((`situation_detail_depense`.`jour` >= (curdate() - interval 30 day)) and (`situation_detail_depense`.`jour` <= curdate())) group by cast(`situation_detail_depense`.`jour` as date)) `dep` on((`d`.`date_jour` = `dep`.`date_depense`))) order by `d`.`date_jour`  ;

