--
-- Structure for view `situation_detail_depense`
--
DROP TABLE IF EXISTS `situation_detail_depense`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `situation_detail_depense`  AS SELECT year(`d`.`date_depense`) AS `annee`, month(`d`.`date_depense`) AS `mois`, cast(`d`.`date_depense` as date) AS `jour`, `tp`.`libelle` AS `type_depense`, count(0) AS `nombre_depenses`, sum(`d`.`montant_depense`) AS `total_depenses` FROM (`depenses` `d` join `type_depenses` `tp` on((`tp`.`id` = `d`.`id_type_depense`))) WHERE (`d`.`isValid` = true) GROUP BY `tp`.`libelle`, year(`d`.`date_depense`), month(`d`.`date_depense`), cast(`d`.`date_depense` as date) WITH ROLLUP ;

