--
-- Structure for view `situation_detail_vente`
--
DROP TABLE IF EXISTS `situation_detail_vente`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `situation_detail_vente`  AS SELECT year(`ventes`.`date_vente`) AS `annee`, month(`ventes`.`date_vente`) AS `mois`, cast(`ventes`.`date_vente` as date) AS `jour`, `ventes`.`type_vente` AS `type_vente`, count(0) AS `nombre_ventes`, sum(`ventes`.`montant`) AS `total_ventes` FROM `ventes` GROUP BY `ventes`.`type_vente`, year(`ventes`.`date_vente`), month(`ventes`.`date_vente`), cast(`ventes`.`date_vente` as date) WITH ROLLUP ORDER BY coalesce(`annee`,9999) DESC, coalesce(`mois`,99) DESC, coalesce(`jour`,'9999-12-31') DESC ;

