--
-- Structure for view `situation_general`
--
DROP TABLE IF EXISTS `situation_general`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `situation_general`  AS SELECT `r1`.`total_vente` AS `total_vente`, `r4`.`montant_paiement` AS `montant_paiement`, (`r1`.`total_vente` - `r4`.`montant_paiement`) AS `montant_credit`, `r2`.`total_depense` AS `total_depense`, `r3`.`total_salaire` AS `total_salaire` FROM (((((select 1 AS `l`,sum(`v`.`montant`) AS `total_vente` from `ventes` `v`) `r1` left join (select 1 AS `l`,sum(`d`.`montant_depense`) AS `total_depense` from `depenses` `d`) `r2` on((`r1`.`l` = `r2`.`l`))) left join (select 1 AS `l`,sum(((`s`.`montant_salaire` + `s`.`montant_credit`) + `s`.`montant_gratification`)) AS `total_salaire` from `salaires` `s`) `r3` on((`r1`.`l` = `r3`.`l`))) left join (select 1 AS `l`,sum(`p`.`montant`) AS `montant_paiement` from `paiements` `p`) `r4` on((`r4`.`l` = `r1`.`l`))) left join (select 1 AS `l`,(count(`vp`.`id`) - 1) AS `nbre_client` from `clients` `vp`) `r5` on((`r5`.`l` = `r1`.`l`))) ;

