--
-- Structure for view `tendant_client_10`
--
DROP TABLE IF EXISTS `tendant_client_10`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `tendant_client_10`  AS WITH   `ventes_par_mois` as (select `v`.`id_client` AS `id_client`,month(`v`.`createdAt`) AS `mois`,year(`v`.`createdAt`) AS `annee`,sum((`v`.`quantite` * `v`.`prix_unitaire`)) AS `total_mois` from `ventes` `v` group by `v`.`id_client`,month(`v`.`createdAt`),year(`v`.`createdAt`)), `dernier_mois` as (select `ventes_par_mois`.`id_client` AS `id_client`,`ventes_par_mois`.`mois` AS `mois`,`ventes_par_mois`.`annee` AS `annee`,`ventes_par_mois`.`total_mois` AS `total_dernier_mois` from `ventes_par_mois` where ((`ventes_par_mois`.`annee`,`ventes_par_mois`.`mois`) = (select year(curdate()),month(curdate())))), `avant_dernier_mois` as (select `ventes_par_mois`.`id_client` AS `id_client`,`ventes_par_mois`.`mois` AS `mois`,`ventes_par_mois`.`annee` AS `annee`,`ventes_par_mois`.`total_mois` AS `total_avant_dernier_mois` from `ventes_par_mois` where ((`ventes_par_mois`.`annee`,`ventes_par_mois`.`mois`) = (select year((curdate() - interval 1 month)),month((curdate() - interval 1 month))))) select `c`.`id` AS `id`,`c`.`nom` AS `nom`,`c`.`prenom` AS `prenom`,coalesce(`dm`.`total_dernier_mois`,0) AS `total_mois_courant`,coalesce(`adm`.`total_avant_dernier_mois`,0) AS `total_mois_precedent`,(case when (coalesce(`adm`.`total_avant_dernier_mois`,0) = 0) then 'new' when (coalesce(`dm`.`total_dernier_mois`,0) > coalesce(`adm`.`total_avant_dernier_mois`,0)) then 'up' when (coalesce(`dm`.`total_dernier_mois`,0) < coalesce(`adm`.`total_avant_dernier_mois`,0)) then 'down' else 'stable' end) AS `tendance`,(select max(`ventes`.`createdAt`) from `ventes` where (`ventes`.`id_client` = `c`.`id`)) AS `derniere_vente` from ((`clients` `c` left join `dernier_mois` `dm` on((`c`.`id` = `dm`.`id_client`))) left join `avant_dernier_mois` `adm` on((`c`.`id` = `adm`.`id_client`))) order by coalesce(`dm`.`total_dernier_mois`,0) desc limit 10  ;

